//! Deterministic starter brush profiles and stroke resampling.
#![allow(missing_docs)]
#![allow(
    clippy::missing_errors_doc,
    clippy::missing_panics_doc,
    clippy::must_use_candidate
)]

pub mod pack;
pub mod v2;

pub use pack::*;
pub use v2::*;

use ink_input::PointerSample;
use ink_model::{BrushId, Rgba8};
use std::fmt;

/// Upper bound for work generated by one stroke replay. A diagonal across the
/// largest v1 canvas with the smallest starter spacing remains below this cap.
pub const MAX_RESAMPLED_DABS: usize = 262_144;

/// Built-in brush behavior available in Phase 1.
#[derive(Clone, Copy, Debug, Eq, PartialEq)]
pub enum BrushKind {
    TechnicalPen,
    Pencil,
    OpaqueRound,
    SoftAirbrush,
    Marker,
}

/// A declarative brush preset.
#[derive(Clone, Copy, Debug, PartialEq)]
pub struct BrushPreset {
    pub id: BrushId,
    pub kind: BrushKind,
    pub diameter_px: f32,
    pub opacity: f32,
    pub spacing: f32,
    pub color: Rgba8,
}

impl BrushPreset {
    /// Starter presets intentionally have no executable/plugin code.
    #[must_use]
    pub const fn starters() -> [Self; 5] {
        let color = Rgba8 {
            r: 20,
            g: 20,
            b: 24,
            a: 255,
        };
        [
            Self {
                id: BrushId::from_u128(1),
                kind: BrushKind::TechnicalPen,
                diameter_px: 4.0,
                opacity: 1.0,
                spacing: 0.1,
                color,
            },
            Self {
                id: BrushId::from_u128(2),
                kind: BrushKind::Pencil,
                diameter_px: 6.0,
                opacity: 0.55,
                spacing: 0.1,
                color,
            },
            Self {
                id: BrushId::from_u128(3),
                kind: BrushKind::OpaqueRound,
                diameter_px: 24.0,
                opacity: 1.0,
                spacing: 0.1,
                color,
            },
            Self {
                id: BrushId::from_u128(4),
                kind: BrushKind::SoftAirbrush,
                diameter_px: 80.0,
                opacity: 0.18,
                spacing: 0.1,
                color,
            },
            Self {
                id: BrushId::from_u128(5),
                kind: BrushKind::Marker,
                diameter_px: 14.0,
                opacity: 0.8,
                spacing: 0.1,
                color,
            },
        ]
    }
}

/// A position/pressure dab emitted by resampling.
#[derive(Clone, Copy, Debug, PartialEq)]
pub struct Dab {
    pub x: f32,
    pub y: f32,
    pub pressure: f32,
}

/// Brush input that would require unreasonable CPU or memory.
#[derive(Clone, Copy, Debug, Eq, PartialEq)]
pub enum BrushError {
    TooManyDabs,
}

impl fmt::Display for BrushError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            Self::TooManyDabs => f.write_str("stroke exceeds the resampling safety limit"),
        }
    }
}

impl std::error::Error for BrushError {}

/// Velocity-aware low-pass plus deterministic distance resampling.
pub fn resample(samples: &[PointerSample], preset: BrushPreset) -> Result<Vec<Dab>, BrushError> {
    let (dabs, _) = resample_from(samples, preset, None)?;
    Ok(dabs)
}

/// Resample only the newly received samples, continuing from the previous
/// spacing anchor. This is equivalent to [`resample`] over the full input
/// stream, while avoiding a full-path replay for every pointer packet.
pub fn resample_from(
    samples: &[PointerSample],
    preset: BrushPreset,
    previous_anchor: Option<Dab>,
) -> Result<(Vec<Dab>, Option<Dab>), BrushError> {
    if samples.is_empty() {
        return Ok((Vec::new(), previous_anchor));
    }
    let spacing = (preset.diameter_px * preset.spacing).max(0.25);
    let mut anchor = previous_anchor.or_else(|| {
        samples.first().map(|first| Dab {
            x: first.canvas_x,
            y: first.canvas_y,
            pressure: f32::from(first.pressure) / f32::from(u16::MAX),
        })
    });
    let mut result = Vec::new();
    let start_index = usize::from(previous_anchor.is_none());
    if previous_anchor.is_none()
        && let Some(first) = samples.first()
    {
        let dab = Dab {
            x: first.canvas_x,
            y: first.canvas_y,
            pressure: f32::from(first.pressure) / f32::from(u16::MAX),
        };
        result.push(dab);
    }
    for sample in samples.iter().skip(start_index) {
        let Some(mut current_anchor) = anchor else {
            continue;
        };
        let target = Dab {
            x: sample.canvas_x,
            y: sample.canvas_y,
            pressure: f32::from(sample.pressure) / f32::from(u16::MAX),
        };
        let dx = target.x - current_anchor.x;
        let dy = target.y - current_anchor.y;
        let distance = dx.hypot(dy);
        if distance < spacing {
            continue;
        }
        #[allow(clippy::cast_possible_truncation, clippy::cast_sign_loss)]
        let steps = (distance / spacing).floor() as usize;
        if result.len().saturating_add(steps) > MAX_RESAMPLED_DABS {
            return Err(BrushError::TooManyDabs);
        }
        for step in 1..=steps {
            #[allow(clippy::cast_precision_loss)]
            let fraction = (step as f32 * spacing / distance).min(1.0);
            let dab = Dab {
                x: current_anchor.x + dx * fraction,
                y: current_anchor.y + dy * fraction,
                pressure: current_anchor.pressure
                    + (target.pressure - current_anchor.pressure) * fraction,
            };
            result.push(dab);
        }
        current_anchor = target;
        anchor = Some(current_anchor);
    }
    Ok((result, anchor))
}

#[cfg(test)]
mod tests {
    use super::*;
    use ink_input::{DeviceKind, Phase};
    fn sample(x: f32) -> PointerSample {
        PointerSample {
            pointer_id: 1,
            flags: 1,
            device_kind: DeviceKind::Stylus,
            phase: Phase::Move,
            canvas_x: x,
            canvas_y: 0.0,
            pressure: u16::MAX,
            tilt_x: 0.0,
            tilt_y: 0.0,
            azimuth: 0.0,
            twist: 0.0,
            timestamp_ns: 0,
            sequence: 0,
        }
    }
    #[test]
    fn starter_presets_and_spacing_are_deterministic() {
        let preset = BrushPreset::starters()[0];
        assert_eq!(BrushPreset::starters().len(), 5);
        let dabs = resample(&[sample(0.0), sample(10.0)], preset).expect("bounded stroke");
        assert_eq!(dabs.len(), 26);
        assert!((dabs[1].x - 0.4).abs() < f32::EPSILON);
    }

    #[test]
    fn resampling_has_a_hard_work_limit() {
        let preset = BrushPreset::starters()[0];
        assert_eq!(
            resample(&[sample(0.0), sample(105_000.0)], preset),
            Err(BrushError::TooManyDabs)
        );
    }

    #[test]
    fn incremental_resampling_matches_a_full_path_across_packet_boundaries() {
        let preset = BrushPreset::starters()[0];
        let path = (0..257)
            .map(|index| {
                #[allow(clippy::cast_precision_loss)]
                let mut point = sample(index as f32 * 0.13);
                point.pressure = if index % 2 == 0 { 0 } else { u16::MAX };
                point
            })
            .collect::<Vec<_>>();
        let expected = resample(&path, preset).expect("whole path fits");
        let mut anchor = None;
        let mut actual = Vec::new();
        for packet in path.chunks(7) {
            let (dabs, next_anchor) =
                resample_from(packet, preset, anchor).expect("incremental packet fits");
            actual.extend(dabs);
            anchor = next_anchor;
        }
        assert_eq!(actual, expected);
    }
}
